\title{Explicit Bias and Pure Periodicity for the Cusick Density\\of the Binary Digit Sum}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
Let $\stwo(n)$ denote the binary sum-of-digits function (the number of ones in the
base-$2$ expansion of $n$). For a fixed shift $t \ge 1$, Cusick's density is the
asymptotic frequency
\[
  c_t = \lim_{N\to\infty} \frac{1}{N}\,\#\bigl\{\,0 \le n < N : \stwo(n) \le \stwo(n+t)\,\bigr\}.
\]
Cusick conjectured, and Drmota--Kauers--Spiegelhofer (2016) proved, that
$c_t \ge \tfrac12 + 2^{-(2 \stwo(t)+1)}$ for every $t$. This paper develops a
self-contained, machine-verified theory of the structural backbone of this
phenomenon. We establish: (i) the foundational arithmetic of $\stwo$---Legendre's
additive formula $\stwo(n) + \vtwo(n!) = n$, subadditivity
$\stwo(a+b) \le \stwo(a)+\stwo(b)$, and the exact dyadic block average; (ii) the
Kummer reformulation expressing the Cusick inequality as a carry-budget condition
$\carries(t,n) \le \stwo(t)$; (iii) a doubling invariance yielding $c_{2^k} = 3/4$
for all $k$; (iv) the exact values $c_1 = 3/4$ and $c_3 = 11/16$ via residue
counting; and (v) the central pure periodicity theorem: for every $t$, the Cusick
predicate depends only on $n \bmod 2^{L + \stwo(t)}$ (where $t < 2^L$), forcing
$c_t$ to be a dyadic rational and giving an exact period-scaling identity. From (v)
we extract an explicit-bias propagation engine: any finite per-period surplus $d$
over period $P$ propagates to the uniform bound $c_t \ge 1/2 + d/P$ across all
windows. All results have been formalized and verified in Lean~4 with Mathlib; we
present mathematical statements and proof sketches.
\end{abstract}

\section{Introduction}

\subsection{The problem}
The binary sum-of-digits function $\stwo : \NN \to \NN$ counts the ones in a
number's binary expansion. Adding a fixed shift $t$ perturbs this count in a way
governed entirely by carry propagation: a long run of trailing ones can collapse
into a single higher one, sharply decreasing the digit sum, while in the absence of
carries the digit sums simply add.

Thomas Cusick asked: for fixed $t$, what is the density of $n$ for which adding $t$
does not decrease the digit sum? Writing the \emph{Cusick predicate}
$P_t(n) :\equiv (\stwo(n) \le \stwo(n+t))$, the density is
$c_t = \dens\,\{ n : P_t(n) \}$. The naive expectation $c_t = 1/2$ is wrong: the
density is always strictly above $1/2$. Cusick conjectured the explicit bound
\begin{equation}\label{eq:star}
  c_t \ge \frac12 + 2^{-(2 \stwo(t)+1)},
\end{equation}
later proved by Drmota, Kauers, and Spiegelhofer using transfer-operator and
automaton methods. The bias term decays with the binary weight $\stwo(t)$ but is
never zero.

\subsection{Contributions}
This paper isolates and rigorously establishes the elementary, structural layer
beneath~\eqref{eq:star}, with complete formal verification:
\begin{enumerate}
  \item \textbf{Foundations} (\S\ref{sec:found}): Legendre's additive identity,
  subadditivity of $\stwo$, and the exact dyadic block sum.
  \item \textbf{Carry reformulation} (\S\ref{sec:carry}): via Kummer's theorem,
  $P_t(n)$ is equivalent to $\carries(t,n) \le \stwo(t)$.
  \item \textbf{Doubling invariance} (\S\ref{sec:double}): the count
  self-similarity $\cusickCount(2t,2N) = 2\,\cusickCount(t,N)$ and $c_{2^k} = 3/4$.
  \item \textbf{Exact small densities} (\S\ref{sec:small}): $c_1 = 3/4$ and
  $c_3 = 11/16$.
  \item \textbf{Pure periodicity} (\S\ref{sec:period}): $P_t$ is purely periodic
  with period $2^{L+\stwo(t)}$, so $c_t$ is a dyadic rational.
  \item \textbf{Propagation engine} (\S\ref{sec:engine}): a finite per-period
  surplus $d$ propagates to $c_t \ge 1/2 + d/P$.
\end{enumerate}
Throughout, $\vtwo(m)$ is the $2$-adic valuation and $\NN = \{0,1,2,\dots\}$.

\section{Foundations: the binary digit sum}\label{sec:found}

\begin{definition}[Binary digit sum]
For $n \in \NN$, $\stwo(n) = \sum_i d_i$ where $n = \sum_i d_i 2^i$ with
$d_i \in \{0,1\}$. Immediately $\stwo(0)=0$, $\stwo(1)=1$, $\stwo(n) \le n$.
\end{definition}

\begin{theorem}[Legendre's formula, additive form]\label{thm:legendre}
For all $n$, $\;\stwo(n) + \vtwo(n!) = n$.
\end{theorem}
\begin{proof}[Proof sketch]
Legendre's formula $(p-1)\vtwo(n!) = n - s_p(n)$ at $p=2$ gives
$\vtwo(n!) = n - \stwo(n)$; rearranging, using $\stwo(n) \le n$, yields the
identity.
\end{proof}

\begin{lemma}[Monotonicity of $\vtwo$ under divisibility]\label{lem:mono}
If $m \mid k$ and $k \ne 0$ then $\vtwo(m) \le \vtwo(k)$.
\end{lemma}

\begin{theorem}[Subadditivity]\label{thm:subadd}
For all $a,b$, $\;\stwo(a+b) \le \stwo(a) + \stwo(b)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\binom{a+b}{a}$ is an integer, so $a!\,b! \mid (a+b)!$. By Lemma~\ref{lem:mono},
$\vtwo(a!)+\vtwo(b!) \le \vtwo((a+b)!)$. Applying Theorem~\ref{thm:legendre} to
$a$, $b$, $a+b$ and eliminating the valuations gives the claim.
\end{proof}

The special case $\stwo(n+1) \le \stwo(n)+1$ is used repeatedly.

\begin{theorem}[Exact dyadic block average]\label{thm:block}
For all $k$, $\;\sum_{x=0}^{2^k-1} \stwo(x) = k\cdot 2^{k-1}$. Hence the mean of
$\stwo$ over $[0,2^k)$ is $k/2$.
\end{theorem}

\section{The carry reformulation (Kummer)}\label{sec:carry}

\begin{definition}[Carry count]
$\carries(t,n) = \vtwo\binom{n+t}{t}$, the number of carries when adding $n$ and
$t$ in base $2$ (Kummer).
\end{definition}

\begin{theorem}[Kummer, subtraction form]\label{thm:kummer}
$\carries(t,n) = \stwo(t) + \stwo(n) - \stwo(n+t)$.
\end{theorem}

\begin{theorem}[Additive carry identity]\label{thm:addcarry}
$\stwo(n+t) + \carries(t,n) = \stwo(n) + \stwo(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Immediate from Theorem~\ref{thm:kummer} and subadditivity
(Theorem~\ref{thm:subadd}), which keeps the subtraction genuine.
\end{proof}

\begin{theorem}[Cusick inequality as carry counting]\label{thm:reform}
$\stwo(n) \le \stwo(n+t) \iff \carries(t,n) \le \stwo(t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Rearrange Theorem~\ref{thm:addcarry}: $\stwo(n+t)-\stwo(n) = \stwo(t)-\carries(t,n)$.
\end{proof}

\begin{corollary}[No-carry extremal case]
If $\carries(t,n)=0$ then $\stwo(n+t) = \stwo(n)+\stwo(t)$, the maximal gain.
\end{corollary}

\begin{remark}
The one-sided bound $\carries(t,n) \le \stwo(t)$ can fail (e.g.\ $n=3,t=1$); only
the symmetric $\carries(t,n) \le \stwo(n)+\stwo(t)$ is unconditional.
\end{remark}

\section{Doubling invariance and powers of two}\label{sec:double}

\begin{lemma}[Low-bit recursion]\label{lem:lowbit}
$\stwo(2n) = \stwo(n)$ and $\stwo(2n+1) = \stwo(n)+1$.
\end{lemma}

\begin{theorem}[Doubling invariance]\label{thm:double}
$\stwo(2n) \le \stwo(2n+2t) \iff \stwo(n) \le \stwo(n+t)$, and likewise on the odd
fibre $\stwo(2n+1) \le \stwo(2n+1+2t) \iff \stwo(n) \le \stwo(n+t)$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $2n+2t = 2(n+t)$, $2n+1+2t = 2(n+t)+1$, and apply Lemma~\ref{lem:lowbit}.
\end{proof}

\begin{definition}[Cusick count]
$\cusickCount(t,N) = \#\{ n < N : \stwo(n) \le \stwo(n+t)\}$.
\end{definition}

\begin{theorem}[Count self-similarity]\label{thm:self}
$\cusickCount(2t,2N) = 2\,\cusickCount(t,N)$.
\end{theorem}
\begin{proof}[Proof sketch]
Split $[0,2N)$ into even and odd fibres; by Theorem~\ref{thm:double} each
contributes $\cusickCount(t,N)$.
\end{proof}

\begin{theorem}[Pointwise criterion for powers of two]
$\stwo(n) \le \stwo(n+2^k) \iff (n/2^k) \bmod 4 \ne 3$.
\end{theorem}

\begin{theorem}[Density of power-of-two shifts]\label{thm:pow2}
For all $k,m$, $\;\cusickCount(2^k, 2^{k+2}m) = 3\cdot 2^k m$, i.e.\ $c_{2^k} = 3/4$
with bias $1/4$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$; base $c_1=3/4$ (Theorem~\ref{thm:t1}), step by
Theorem~\ref{thm:self}.
\end{proof}

\begin{theorem}[Full orbit invariance]
$\cusickCount(2^k t, 2^k N) = 2^k\,\cusickCount(t,N)$; hence $c_t$ depends only on
the odd part of $t$.
\end{theorem}

\section{Exact small densities}\label{sec:small}

\begin{theorem}[Digit concatenation]\label{thm:concat}
For $a < 2^M$, $\;\stwo(2^M b + a) = \stwo(b) + \stwo(a)$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $M$ via Lemma~\ref{lem:lowbit}: low and high digit strings concatenate
without interaction.
\end{proof}

\subsection{The shift $t=1$}

\begin{theorem}[$t=1$ criterion]\label{thm:t1iff}
$\stwo(n) \le \stwo(n+1) \iff n \bmod 4 \ne 3$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:reform} the condition is $\carries(1,n) \le 1$. Since
$\binom{n+1}{1}=n+1$, $\carries(1,n)=\vtwo(n+1)$, so the condition is $4 \nmid (n+1)$.
\end{proof}

\begin{theorem}[Exact density $c_1 = 3/4$]\label{thm:t1}
$\#\{n < 4m : \stwo(n) \le \stwo(n+1)\} = 3m$, so $c_1 = 3/4 = 1/2 + 1/4$.
\end{theorem}

\begin{theorem}[Infinitude of the good set]
For every $t$, $\{n : \stwo(n) \le \stwo(n+t)\}$ is infinite, witnessed by
$n = 2^{j+t}$.
\end{theorem}

\subsection{The shift $t=3$}

\begin{theorem}[$t=3$ criterion]\label{thm:t3iff}
$\stwo(n) \le \stwo(n+3) \iff n \bmod 16 \notin \{5,7,13,14,15\}$.
\end{theorem}
\begin{proof}[Proof sketch]
Split $n = 16b+a$; by Theorem~\ref{thm:concat}, $\stwo(n) = \stwo(b)+\stwo(a)$. For
$a \le 12$ the predicate depends only on $a$; for $a \in \{13,14,15\}$ overflow
makes it false for every $b$ by subadditivity.
\end{proof}

\begin{theorem}[Exact density $c_3 = 11/16$]\label{thm:t3}
$\cusickCount(3,16m) = 11m$, so $c_3 = 11/16$. Moreover
$32\,\cusickCount(3,16m) \ge 17\cdot 16m$, clearing the floor~\eqref{eq:star} by
$5/32$.
\end{theorem}

\begin{theorem}[Orbit density for $t=3$]
$\cusickCount(2^k\cdot 3, 2^k\cdot 16m) = 2^k\cdot 11m$, so $c_{3\cdot 2^k}=11/16$.
\end{theorem}

\begin{remark}
$c_1 = 12/16 \ne 11/16 = c_3$, and equal-weight shifts may differ: $c_t$ is
sensitive to the gap structure of the binary expansion, not just $\stwo(t)$.
\end{remark}

\section{Pure periodicity and rationality}\label{sec:period}

\begin{lemma}[All-ones digit sum]
$\stwo(2^s - 1) = s$.
\end{lemma}

\begin{lemma}[Strict subadditivity on overflow]\label{lem:strict}
If $a,t < 2^L$ and $2^L \le a+t$ then $\stwo(a+t) < \stwo(a) + \stwo(t)$.
\end{lemma}
\begin{proof}[Proof sketch]
Overflow forces $\ge 1$ carry, so by Theorem~\ref{thm:addcarry} the digit sum
strictly drops.
\end{proof}

\begin{lemma}[Overflow forces the predicate false]\label{lem:overflow}
Let $M = L + \stwo(t)$ with $t < 2^L$, $t \ge 1$. If $a < 2^M$ and $2^M \le a+t$,
then for every $b$, $\;\stwo(2^M b + a + t) < \stwo(2^M b + a)$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $a = 2^L q + a_0$, $a_0 < 2^L$, $q < 2^{\stwo(t)}$. Overflow forces
$q = 2^{\stwo(t)}-1$ (all-ones high block) and $2^L \le a_0 + t$. By
Theorem~\ref{thm:concat},
$\stwo(2^M b + a) = \stwo(b) + \stwo(t) + \stwo(a_0)$ and
$\stwo(2^M b + a + t) = \stwo(b+1) + \stwo(r)$ with $r = a_0 + t - 2^L$. Combining
strict subadditivity (Lemma~\ref{lem:strict}) with $\stwo(b+1) \le \stwo(b)+1$
gives the strict inequality for all $b$.
\end{proof}

\begin{theorem}[Pure periodicity]\label{thm:periodic}
For every $t \ge 1$ and $L$ with $t < 2^L$, writing $P = 2^{L+\stwo(t)}$,
\[
  \stwo(n) \le \stwo(n+t) \iff \stwo(n \bmod P) \le \stwo((n \bmod P) + t).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Write $n = Pb + a$, $a = n \bmod P$. If $a + t \ge P$, Lemma~\ref{lem:overflow}
makes both sides false. Otherwise Theorem~\ref{thm:concat} reduces the predicate to
$\stwo(a) \le \stwo(a+t)$, independent of $b$.
\end{proof}

\begin{theorem}[Period scaling]\label{thm:scale}
For all $t \ge 1$ with $t < 2^L$ and all $m$, with $P = 2^{L+\stwo(t)}$,
\[
  \cusickCount(t, P m) = m \cdot \cusickCount(t, P).
\]
Hence $c_t = \cusickCount(t,P)/P$ is a dyadic rational.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $m$; each block contributes the base-block count by
Theorem~\ref{thm:periodic}.
\end{proof}

\section{The explicit-bias propagation engine}\label{sec:engine}

\begin{theorem}[Bias propagation]\label{thm:prop}
Let $t \ge 1$, $t < 2^L$, $P = 2^{L+\stwo(t)}$. If
$2\,\cusickCount(t,P) \ge P + 2d$, then for every $m$,
\[
  2\,\cusickCount(t, P m) \ge P m + 2 d m,
\]
equivalently $c_t \ge \tfrac12 + d/P$.
\end{theorem}
\begin{proof}[Proof sketch]
Multiply the hypothesis by $m$ and substitute Theorem~\ref{thm:scale}.
\end{proof}

Instantiating: $t=1$ gives $d=1$, $P=4$ ($c_1 \ge 1/2 + 1/4$); $t=3$ gives $d=3$,
$P=16$ ($c_3 \ge 1/2 + 3/16$). The engine separates the finite per-period
computation of $d$ from the universal scaling; it propagates any established
per-period bias but does not by itself prove $d > 0$ for general $t$.

\section{Algorithms}

\textbf{(A) Digit sum:} compute $\stwo(n)$ by repeated division by $2$,
$O(\log n)$. \textbf{(B) Carry count:} $\carries(t,n) = \stwo(t)+\stwo(n)-\stwo(n+t)$
(Theorem~\ref{thm:kummer}), $O(\log(n+t))$. \textbf{(C) Exact density:} with
$L = \lceil\log_2(t+1)\rceil$, $P = 2^{L+\stwo(t)}$, count good residues in
$[0,P)$ and return $\cusickCount(t,P)/P$ (Theorems~\ref{thm:periodic},
\ref{thm:scale}), $O(P\log P)$. \textbf{(D) Bias propagation:} from surplus $d$
return the certified window bound (Theorem~\ref{thm:prop}), $O(1)$.

\section{Applications and discussion}

The binary digit sum defines the Thue--Morse sequence $t_n = \stwo(n) \bmod 2$, a
paradigm of deterministic pseudorandomness; the bias here is a quantitative
manifestation of its correlations. It appears in Gelfond-type equidistribution and
in recent work on primes with prescribed digit sums. The carry reformulation
connects to the analysis of binary adder circuits, where carry chains determine
latency. Methodologically, the carry reformulation is the conceptual fulcrum, and
pure periodicity is what renders the densities rational and tractable.

\section{Future directions}

\begin{conjecture}[Bit-reversal symmetry]
For odd $t$, $c_t = c_{\mathrm{rev}(t)}$ where $\mathrm{rev}$ reverses the binary
digit string. Evidence: $c_{11} = c_{13} = 19/32$, $c_{19} = c_{25} = 41/64$.
\end{conjecture}

\begin{conjecture}[Gap structure, not weight]
$c_t$ depends on the multiset of gaps between consecutive $1$-bits of the odd part
of $t$, not on $\stwo(t)$ alone. Evidence: $c_3 \ne c_5$.
\end{conjecture}

\begin{conjecture}[Gap-separation decoupling]
If $t = 2^a + 2^b$, $a < b$, then $c_t$ depends only on $b-a$, and
$c_{2^a+2^b} = 11/16$ once $b - a \ge 3$; more generally, well-separated bits
decouple with a product formula $c_t = 1 - (1 - c_{\text{single bit}})^{\stwo(t)}$.
\end{conjecture}

\begin{conjecture}[All-ones extremal at fixed weight]
Among $t$ with $\stwo(t) = s$, the all-ones shift $t = 2^s - 1$ maximizes $c_t$.
\end{conjecture}

\begin{conjecture}[Closed form for the all-ones family]
Writing $c_{2^s-1} = 1/2 + a_s/4^s$, the values $a_1=1, a_2=3, a_3=11, a_4=43$
(from $c_1=3/4$, $c_3=11/16$, $c_7=43/64$, $c_{15}=171/256$) satisfy
$a_{s+1} = 4a_s - 1$; equivalently the per-period counts $3,11,43,171$ satisfy
$\text{next} = 4\cdot\text{prev}-1$.
\end{conjecture}

\section{Conclusion}

We have given a complete, machine-verified account of the elementary skeleton
driving the Cusick bias: Legendre's formula and subadditivity of $\stwo$; Kummer's
carry reformulation; a doubling symmetry propagating $c_1 = 3/4$ to all powers of
two; exact densities $c_1 = 3/4$ and $c_3 = 11/16$; and the central pure
periodicity theorem forcing every $c_t$ to be a dyadic rational, packaged as a
finite-input, uniform-output bias-propagation engine. The deep asymptotic content
of~\eqref{eq:star} for arbitrary $t$ remains the province of transfer-operator
methods, but its rational, periodic backbone is now fully and rigorously in hand.

