from fractions import Fraction


def s2(n: int) -> int:
    """Binary sum-of-digits: number of 1-bits of n."""
    return bin(n).count("1")


def period(t: int) -> int:
    """Fundamental period P = 2^{L + s2(t)} of the Cusick predicate P_t."""
    L = max(1, t.bit_length())  # smallest L with t < 2^L
    return 2 ** (L + s2(t))


def cusick_count(t: int, N: int) -> int:
    """#{ n < N : s2(n) <= s2(n + t) }."""
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))


def exact_cusick_density(t: int) -> Fraction:
    """Exact c_t as a dyadic rational = (count over one period) / period.

    Justified by pure periodicity (P_t depends only on n mod P) and the
    period-scaling identity cusickCount(t, P*m) = m * cusickCount(t, P).
    Complexity: O(P log P) with P = 2^{L + s2(t)}.
    """
    P = period(t)
    return Fraction(cusick_count(t, P), P)

def s2(n: int) -> int:
    """Binary sum-of-digits."""
    return bin(n).count("1")


def carries(t: int, n: int) -> int:
    """Number of carries when adding n and t in base 2.

    By Kummer's theorem the carry count equals v2(C(n+t, t)); the additive
    identity s2(n+t) + carries = s2(n) + s2(t) lets us compute it from three
    digit sums in O(log(n+t)), with no factorial or binomial arithmetic.
    """
    return s2(t) + s2(n) - s2(n + t)


def cusick_holds(t: int, n: int) -> bool:
    """P_t(n): adding t does not decrease the digit sum.

    Equivalent (Kummer reformulation) to carries(t, n) <= s2(t).
    """
    return carries(t, n) <= s2(t)

from fractions import Fraction
from typing import Tuple


def s2(n: int) -> int:
    return bin(n).count("1")


def period(t: int) -> int:
    return 2 ** (max(1, t.bit_length()) + s2(t))


def cusick_count(t: int, N: int) -> int:
    return sum(1 for n in range(N) if s2(n) <= s2(n + t))


def propagate_bias(t: int) -> Tuple[int, int, Fraction]:
    """Turn a single finite per-period surplus d into the uniform bias bound.

    Computes d = cusickCount(t, P) - P//2 over one period P, and certifies that
    2 * cusickCount(t, P*m) >= P*m + 2*d*m for all m, i.e. c_t >= 1/2 + d/P.
    Returns (P, d, bias). Complexity: one O(P log P) period count, then O(1).
    """
    P = period(t)
    d = cusick_count(t, P) - P // 2
    return P, d, Fraction(d, P)
